/// Look a tool up by its snake_case name.
pub fn tool_by_name(name: &str) -> Option<&'static ToolStats> {
    TOOLS
        .binary_search_by(|tool| tool.name.cmp(name))
        .ok()
        .map(|index| &TOOLS[index])
}

/// Look a tool up by its game id.
pub fn tool_by_id(id: i64) -> Option<&'static ToolStats> {
    TOOLS.iter().find(|tool| tool.id == id)
}
